const body = $input.first().json.body;
const required = ['project_name', 'reporting_period', 'status_updates'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.status_updates) || body.status_updates.length === 0) return [{ json: { valid: false, error: 'status_updates must be a non-empty array' } }];
const statuses = ['on_track','at_risk','delayed','blocked','completed','on_hold'];
const overall = statuses.includes(body.overall_status) ? body.overall_status : 'on_track';
const reportTypes = ['weekly','bi_weekly','monthly','milestone','executive','stakeholder'];
const reportType = reportTypes.includes(body.report_type) ? body.report_type : 'weekly';
return [{ json: { valid: true, projectName: body.project_name.trim(), projectDescription: (body.project_description||'').slice(0,400), reportingPeriod: body.reporting_period.trim(), reportType, overallStatus: overall, projectManager: body.project_manager||'', stakeholders: Array.isArray(body.stakeholders)?body.stakeholders:(body.stakeholders||'').split(',').map(s=>s.trim()).filter(Boolean), statusUpdates: body.status_updates.map(u=>({area:u.area||'General',status:u.status||'on_track',update:(u.update||'').slice(0,500),metrics:u.metrics||'',owner:u.owner||''})), completedItems: Array.isArray(body.completed_this_period)?body.completed_this_period:(body.completed_this_period||'').split('\n').map(s=>s.trim()).filter(Boolean), plannedItems: Array.isArray(body.planned_next_period)?body.planned_next_period:(body.planned_next_period||'').split('\n').map(s=>s.trim()).filter(Boolean), blockers: Array.isArray(body.blockers)?body.blockers:(body.blockers||'').split('\n').map(s=>s.trim()).filter(Boolean), risks: Array.isArray(body.risks)?body.risks:(body.risks||'').split('\n').map(s=>s.trim()).filter(Boolean), budget: body.budget||null, budgetSpent: body.budget_spent||null, currency: body.currency||'USD', recipients: Array.isArray(body.recipients)?body.recipients:(body.recipients||'').split(',').map(s=>s.trim()).filter(Boolean), replyEmail: body.reply_email||null, requestedAt: new Date().toISOString() } }];

values.content:
Write a project status report.

Project: {{ $json.projectName }}
Period: {{ $json.reportingPeriod }}
Report type: {{ $json.reportType.replace(/_/g,' ') }}
Overall status: {{ $json.overallStatus.replace(/_/g,' ').toUpperCase() }}
PM: {{ $json.projectManager || 'not specified' }}

Status by area:
{{ $json.statusUpdates.map(u => u.area + ' [' + u.status + ']: ' + u.update + (u.metrics?' | Metrics: '+u.metrics:'') + (u.owner?' | Owner: '+u.owner:'')).join('\n') }}

Completed:
{{ $json.completedItems.join('\n') || 'none' }}

Planned next period:
{{ $json.plannedItems.join('\n') || 'none' }}

Blockers:
{{ $json.blockers.join('\n') || 'none' }}

Risks:
{{ $json.risks.join('\n') || 'none' }}

Budget: {{ $json.budget ? $json.currency + $json.budget + ' total, ' + $json.currency + ($json.budgetSpent||'unknown') + ' spent' : 'not provided' }}

Return this JSON:
{
  "executive_summary": "3-4 sentences: overall health, top accomplishment, most important risk or blocker",
  "status_narrative": "2-3 paragraph narrative synthesizing updates into a coherent picture",
  "highlight": "single most important accomplishment this period",
  "key_risk": "single most important risk or null if all well",
  "blocker_summary": "plain English blocker summary or null if none",
  "next_period_focus": "2-3 sentences on what team will focus on next",
  "action_items_needed": ["specific things needed from stakeholders"]
}

