const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let narrative;
try { narrative = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
narrative._meta = { projectName: input.projectName, reportingPeriod: input.reportingPeriod, reportType: input.reportType, overallStatus: input.overallStatus, projectManager: input.projectManager, statusUpdates: input.statusUpdates, completedItems: input.completedItems, plannedItems: input.plannedItems, blockers: input.blockers, risks: input.risks, budget: input.budget, budgetSpent: input.budgetSpent, currency: input.currency, recipients: input.recipients, replyEmail: input.replyEmail };
return [{ json: narrative }];

const r = $input.first().json;
const m = r._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const statusConfig = { on_track:{color:'#16a34a',bg:'#f0fdf4',label:'ON TRACK'}, at_risk:{color:'#d97706',bg:'#fffbeb',label:'AT RISK'}, delayed:{color:'#ea580c',bg:'#fff7ed',label:'DELAYED'}, blocked:{color:'#dc2626',bg:'#fef2f2',label:'BLOCKED'}, completed:{color:'#2563eb',bg:'#eff6ff',label:'COMPLETED'}, on_hold:{color:'#6b7280',bg:'#f9fafb',label:'ON HOLD'} };
const sc = statusConfig[m.overallStatus] || statusConfig.on_track;
const areaRows = m.statusUpdates.map(u => { const c = (statusConfig[u.status]||statusConfig.on_track).color; return `<div style="border-left:3px solid ${c};padding:10px 16px;background:#fafafa;border-radius:0 6px 6px 0;margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px"><span style="font-size:14px;font-weight:600">${esc(u.area)}</span><span style="background:${c}22;color:${c};font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px">${esc((u.status||'').replace(/_/g,' ').toUpperCase())}</span></div><div style="font-size:14px;color:#374151;line-height:1.6">${esc(u.update)}</div>${u.metrics?`<div style="font-size:12px;color:#6b7280;margin-top:4px">📊 ${esc(u.metrics)}</div>`:''}</div>`; }).join('');
const completed = m.completedItems.map(c => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">✓ ${esc(c)}</div>`).join('');
const planned = m.plannedItems.map(p => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">→ ${esc(p)}</div>`).join('');
const blockerBlock = m.blockers.map(b => `<div style="font-size:14px;padding:5px 0;color:#7f1d1d">🚧 ${esc(b)}</div>`).join('');
const riskBlock = m.risks.map(rk => `<div style="font-size:14px;padding:5px 0;color:#92400e">⚠ ${esc(rk)}</div>`).join('');
const actionItems = (r.action_items_needed||[]).map((a,i) => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #eff6ff;color:#1e40af">${i+1}. ${esc(a)}</div>`).join('');
let budgetBar = '';
if (m.budget && m.budgetSpent) { const pct = Math.min(100,Math.round(parseFloat(m.budgetSpent)/parseFloat(m.budget)*100)); const bc = pct>90?'#dc2626':pct>75?'#d97706':'#16a34a'; budgetBar = `<div style="background:#fff;padding:12px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Budget</div><div style="display:flex;justify-content:space-between;font-size:12px;color:#9ca3af;margin-bottom:4px"><span>${m.currency}${m.budgetSpent} spent</span><span>${m.currency}${m.budget} total (${pct}%)</span></div><div style="background:#f3f4f6;border-radius:4px;height:8px"><div style="background:${bc};height:8px;border-radius:4px;width:${pct}%"></div></div></div>`; }
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111"><div style="max-width:680px;margin:0 auto"><div style="background:#1e293b;color:#fff;padding:18px 28px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:4px">${esc(m.reportType.replace(/_/g,' '))} Status Report · ${esc(m.reportingPeriod)}</div><div style="font-size:19px;font-weight:700">${esc(m.projectName)}</div>${m.projectManager?`<div style="font-size:13px;color:#94a3b8;margin-top:3px">PM: ${esc(m.projectManager)}</div>`:''}</div><div style="background:${sc.bg};padding:12px 28px;border:1px solid ${sc.color}44;border-top:none;display:flex;align-items:center;gap:14px"><span style="background:${sc.color};color:#fff;font-size:12px;font-weight:700;padding:4px 14px;border-radius:12px;white-space:nowrap">${sc.label}</span><p style="font-size:14px;color:#374151;margin:0;line-height:1.6">${esc(r.executive_summary)}</p></div>${r.highlight?`<div style="background:#fff;padding:12px 28px;border:1px solid #e5e7eb;border-top:none;display:flex;gap:10px;align-items:flex-start"><span style="font-size:20px">🌟</span><div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:3px">Highlight this period</div><div style="font-size:14px;color:#374151">${esc(r.highlight)}</div></div></div>`:''}<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Status by area</div>${areaRows}</div><div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="font-size:14px;line-height:1.8;color:#374151;white-space:pre-line">${esc(r.status_narrative)}</div></div>${completed||planned?`<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">${completed?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:8px">Completed</div>${completed}</div>`:''}${planned?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">Planned next period</div>${planned}</div>`:''}</div></div>`:''  }${blockerBlock||riskBlock?`<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">${blockerBlock?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#dc2626;margin-bottom:7px">Blockers</div>${blockerBlock}</div>`:''}${riskBlock?`<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#d97706;margin-bottom:7px">Risks</div>${riskBlock}</div>`:''}</div></div>`:''  }${r.next_period_focus?`<div style="background:#f0f9ff;padding:12px 28px;border:1px solid #bae6fd"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#0369a1;margin-bottom:5px">Next period focus</div><div style="font-size:14px;color:#0c4a6e;line-height:1.65">${esc(r.next_period_focus)}</div></div>`:''  }${actionItems?`<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:7px">Action needed from stakeholders</div>${actionItems}</div>`:''  }${budgetBar}<div style="background:#1e293b;color:#475569;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Project Status · ${esc(m.projectName)} · ${esc(m.reportingPeriod)}</div></div></body></html>`;
return [{ json: { html, recipients: m.recipients, replyEmail: m.replyEmail, projectName: m.projectName, overallStatus: m.overallStatus, reportingPeriod: m.reportingPeriod, report: r } }];
